// Compatibility bridge for the early cardActions data format.
const procKeys=new Set('OnPlay ActivateMain Trigger Passive OnAttack OncePerTurn Counter OnKO DonX YourTurn OpponentTurn EndOfTurn CharacterCount TrashX'.split(' '));
const effectKeys=new Set('DrawCards DonMinus DonTap GainActiveDon GainRestedDon MillDeck BuffSelf BuffCombat BuffAny GainRush Rush Blocker ActivateSelf SelfTap TrashSelf KOCostOrLess'.split(' '));
export function legacySupported(rule){return (rule.cardActions||[]).length>0&&(rule.cardActions||[]).every(a=>Object.keys(a.actionEffect||{}).every(k=>effectKeys.has(k)));}
export function legacyActions(rule){if(!legacySupported(rule))return [];return rule.cardActions.map(a=>{const t=a.actionTrigger||{},x=a.actionEffect||{},proc=Object.fromEntries(Object.entries(t).filter(([k])=>procKeys.has(k)),),effect={};if(t.CharacterCount)proc.CharactersOrMore=t.CharacterCount;if(t.TrashX)proc.TrashXOrMore=t.TrashX;if(t.SelfTap)effect.RestSelf=true;if(x.DrawCards)effect.DrawCards=x.DrawCards;if(x.DonMinus)effect.DonMinus=x.DonMinus;if(x.DonTap)effect.DonTap=x.DonTap;if(x.GainActiveDon)effect.GainActiveDon=x.GainActiveDon;if(x.GainRestedDon)effect.GainRestedDon=x.GainRestedDon;if(x.MillDeck)effect.MillDeck=x.MillDeck;if(x.BuffSelf)effect.BuffPower=x.BuffSelf;if(x.BuffCombat)effect.BuffCombatPower=x.BuffCombat;if(x.BuffAny)effect.BuffPower=x.BuffAny;if(x.GainRush||x.Rush)effect.GainRush=true;if(x.Blocker)effect.GainBlocker=true;if(x.ActivateSelf)effect.Activate=true;if(x.TrashSelf)effect.TrashSelf=true;if(x.KOCostOrLess)effect.KOIfCostXOrLess=x.KOCostOrLess;return {proc,steps:[{effect}]};});}
